-- ── History tables are append-only (§13.3, §14.7) ──────────────────────────
CREATE FUNCTION "ftms_append_only"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION '% is part of the history: % is not allowed', TG_TABLE_NAME, TG_OP
    USING ERRCODE = 'insufficient_privilege';
END $$;

CREATE TRIGGER "ticket_messages_append_only"
  BEFORE UPDATE OR DELETE ON "ticket_messages"
  FOR EACH ROW EXECUTE FUNCTION "ftms_append_only"();
CREATE TRIGGER "ticket_status_changes_append_only"
  BEFORE UPDATE OR DELETE ON "ticket_status_changes"
  FOR EACH ROW EXECUTE FUNCTION "ftms_append_only"();
CREATE TRIGGER "ticket_attachments_append_only"
  BEFORE UPDATE OR DELETE ON "ticket_attachments"
  FOR EACH ROW EXECUTE FUNCTION "ftms_append_only"();
CREATE TRIGGER "group_swap_decisions_append_only"
  BEFORE UPDATE OR DELETE ON "group_swap_decisions"
  FOR EACH ROW EXECUTE FUNCTION "ftms_append_only"();
CREATE TRIGGER "support_tickets_no_delete"
  BEFORE DELETE ON "support_tickets"
  FOR EACH ROW EXECUTE FUNCTION "ftms_append_only"();
CREATE TRIGGER "group_swap_requests_no_delete"
  BEFORE DELETE ON "group_swap_requests"
  FOR EACH ROW EXECUTE FUNCTION "ftms_append_only"();

-- ── Tickets ─────────────────────────────────────────────────────────────────
ALTER TABLE "support_tickets"
  ADD CONSTRAINT "support_tickets_values" CHECK (
    "subject" = btrim("subject") AND "subject" <> '' AND btrim("description") <> '' AND
    ("status" = 'CLOSED') = ("closed_at" IS NOT NULL) AND "number" > 0);
ALTER TABLE "ticket_messages"
  ADD CONSTRAINT "ticket_messages_values" CHECK (
    btrim("body") <> '' AND ("internal" = false OR "author_role" <> 'STUDENT'));
ALTER TABLE "ticket_status_changes"
  ADD CONSTRAINT "ticket_status_changes_values" CHECK (
    "from_status" IS DISTINCT FROM "to_status" AND
    ("changed_by_id" IS NULL) = ("changed_by_role" IS NULL));
ALTER TABLE "ticket_attachments"
  ADD CONSTRAINT "ticket_attachments_values" CHECK (
    "bucket" = 'ticket-attachments' AND "size_bytes" > 0 AND "size_bytes" <= 4194304 AND
    "content_type" IN ('application/pdf', 'image/jpeg', 'image/png', 'image/webp') AND
    btrim("file_name") <> '');

-- A ticket's identity (who, what kind) never changes; a closed ticket stays
-- closed except for staff reopening it; a group-swap ticket follows its request.
CREATE FUNCTION "ftms_check_ticket_update"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NEW."number" <> OLD."number" OR NEW."student_id" <> OLD."student_id"
     OR NEW."created_by_id" <> OLD."created_by_id" OR NEW."category" <> OLD."category"
     OR NEW."created_at" <> OLD."created_at" THEN
    RAISE EXCEPTION 'ticket % cannot be reassigned or recategorized', OLD."id"
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;

CREATE TRIGGER "support_tickets_check"
  BEFORE UPDATE ON "support_tickets"
  FOR EACH ROW EXECUTE FUNCTION "ftms_check_ticket_update"();

-- A message, attachment or status change belongs to its ticket; an attachment
-- sent with a message belongs to that message's ticket.
CREATE FUNCTION "ftms_check_attachment"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NEW."message_id" IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM "ticket_messages" WHERE "id" = NEW."message_id" AND "ticket_id" = NEW."ticket_id"
  ) THEN
    RAISE EXCEPTION 'attachment % belongs to another ticket''s message', NEW."id"
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;

CREATE TRIGGER "ticket_attachments_check"
  BEFORE INSERT ON "ticket_attachments"
  FOR EACH ROW EXECUTE FUNCTION "ftms_check_attachment"();

-- ── Group-swap requests (§14, §16.1) ────────────────────────────────────────
ALTER TABLE "group_swap_requests"
  ADD CONSTRAINT "group_swap_requests_parties" CHECK (
    "requester_id" <> "counterpart_id" AND "requester_group_id" <> "counterpart_group_id");
ALTER TABLE "group_swap_requests"
  ADD CONSTRAINT "group_swap_requests_decisions" CHECK (
    ("status" IN ('COUNTERPART_REJECTED', 'PENDING_FACULTY', 'FACULTY_REJECTED', 'APPROVED')) <= ("counterpart_decided_at" IS NOT NULL) AND
    ("status" <> 'PENDING_COUNTERPART' OR "counterpart_decided_at" IS NULL) AND
    ("status" IN ('FACULTY_REJECTED', 'APPROVED')) = ("faculty_decided_at" IS NOT NULL) AND
    ("status" <> 'FACULTY_REJECTED' OR btrim(coalesce("faculty_reason", '')) <> '') AND
    ("status" = 'COUNTERPART_REJECTED' OR "counterpart_reason" IS NULL) AND
    ("status" IN ('PENDING_COUNTERPART', 'PENDING_FACULTY')) = ("closed_at" IS NULL) AND
    ("status" = 'CANCELLED') = ("cancel_reason" IS NOT NULL));

-- Students' current groups, as the swap rules see them.
CREATE FUNCTION "ftms_active_group"(student UUID) RETURNS UUID LANGUAGE sql STABLE AS $$
  SELECT "group_id" FROM "group_memberships" WHERE "student_id" = student AND "ended_at" IS NULL
$$;

CREATE FUNCTION "ftms_check_group_swap"() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
  allowed BOOLEAN;
  must_match BOOLEAN;
  ticket_category "TicketCategory";
  ticket_student UUID;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW."status" <> 'PENDING_COUNTERPART' THEN
      RAISE EXCEPTION 'a group-swap request starts waiting for the counterpart' USING ERRCODE = 'check_violation';
    END IF;
    SELECT "category", "student_id" INTO ticket_category, ticket_student
      FROM "support_tickets" WHERE "id" = NEW."ticket_id";
    IF ticket_category IS DISTINCT FROM 'GROUP_SWAP' OR ticket_student IS DISTINCT FROM NEW."requester_id" THEN
      RAISE EXCEPTION 'a group-swap request needs the requester''s group-swap ticket' USING ERRCODE = 'check_violation';
    END IF;
  ELSE
    IF NEW."ticket_id" <> OLD."ticket_id" OR NEW."requester_id" <> OLD."requester_id"
       OR NEW."counterpart_id" <> OLD."counterpart_id" OR NEW."requester_group_id" <> OLD."requester_group_id"
       OR NEW."counterpart_group_id" <> OLD."counterpart_group_id" OR NEW."created_at" <> OLD."created_at" THEN
      RAISE EXCEPTION 'group-swap request % cannot change its students or groups', OLD."id"
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW."status" <> OLD."status" THEN
      allowed := (OLD."status", NEW."status") IN (
        ('PENDING_COUNTERPART'::"GroupSwapStatus", 'PENDING_FACULTY'::"GroupSwapStatus"),
        ('PENDING_COUNTERPART', 'COUNTERPART_REJECTED'),
        ('PENDING_COUNTERPART', 'WITHDRAWN'),
        ('PENDING_COUNTERPART', 'CANCELLED'),
        ('PENDING_FACULTY', 'APPROVED'),
        ('PENDING_FACULTY', 'FACULTY_REJECTED'),
        ('PENDING_FACULTY', 'WITHDRAWN'),
        ('PENDING_FACULTY', 'CANCELLED'));
      IF NOT allowed THEN
        RAISE EXCEPTION 'group-swap request % cannot go from % to %', OLD."id", OLD."status", NEW."status"
          USING ERRCODE = 'check_violation';
      END IF;
    ELSIF OLD."status" NOT IN ('PENDING_COUNTERPART', 'PENDING_FACULTY') THEN
      RAISE EXCEPTION 'group-swap request % is decided and cannot change', OLD."id"
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  -- A student takes part in at most one open request (§14.2). The rows of both
  -- students are locked so concurrent requests are judged one after the other.
  IF NEW."status" IN ('PENDING_COUNTERPART', 'PENDING_FACULTY') THEN
    PERFORM 1 FROM "student_profiles"
      WHERE "id" IN (NEW."requester_id", NEW."counterpart_id") ORDER BY "id" FOR UPDATE;
    IF EXISTS (
      SELECT 1 FROM "group_swap_requests" r
      WHERE r."id" <> NEW."id" AND r."status" IN ('PENDING_COUNTERPART', 'PENDING_FACULTY')
        AND (r."requester_id" IN (NEW."requester_id", NEW."counterpart_id")
             OR r."counterpart_id" IN (NEW."requester_id", NEW."counterpart_id"))
    ) THEN
      RAISE EXCEPTION 'a student of request % already takes part in an open group-swap request', NEW."id"
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  -- Creating, accepting and approving all require both students to still be in
  -- the groups the request was made for (before the exchange), and both groups
  -- to be active.
  IF TG_OP = 'INSERT' THEN
    must_match := true;
  ELSE
    must_match := NEW."status" IN ('PENDING_FACULTY', 'APPROVED') AND NEW."status" <> OLD."status";
  END IF;
  IF must_match THEN
    IF "ftms_active_group"(NEW."requester_id") IS DISTINCT FROM NEW."requester_group_id"
       OR "ftms_active_group"(NEW."counterpart_id") IS DISTINCT FROM NEW."counterpart_group_id" THEN
      RAISE EXCEPTION 'the students of request % are no longer in the groups it was made for', NEW."id"
        USING ERRCODE = 'check_violation';
    END IF;
    IF EXISTS (SELECT 1 FROM "training_groups"
               WHERE "id" IN (NEW."requester_group_id", NEW."counterpart_group_id") AND "archived_at" IS NOT NULL) THEN
      RAISE EXCEPTION 'a group of request % is archived', NEW."id" USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
END $$;

CREATE TRIGGER "group_swap_requests_check"
  BEFORE INSERT OR UPDATE ON "group_swap_requests"
  FOR EACH ROW EXECUTE FUNCTION "ftms_check_group_swap"();

-- An approval is only valid together with the exchange itself: when the
-- transaction commits, each student must be in the other's original group
-- (§14.5: never one student's group without the other's).
CREATE FUNCTION "ftms_check_swap_exchanged"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF "ftms_active_group"(NEW."requester_id") IS DISTINCT FROM NEW."counterpart_group_id"
     OR "ftms_active_group"(NEW."counterpart_id") IS DISTINCT FROM NEW."requester_group_id" THEN
    RAISE EXCEPTION 'approved request % must exchange both students'' groups in the same transaction', NEW."id"
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NULL;
END $$;

CREATE CONSTRAINT TRIGGER "group_swap_requests_exchanged"
  AFTER UPDATE ON "group_swap_requests"
  DEFERRABLE INITIALLY DEFERRED
  FOR EACH ROW WHEN (NEW."status" = 'APPROVED' AND OLD."status" <> 'APPROVED')
  EXECUTE FUNCTION "ftms_check_swap_exchanged"();

-- A group-swap ticket always has its request (checked when the transaction commits).
CREATE FUNCTION "ftms_check_swap_ticket"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NEW."category" = 'GROUP_SWAP'
     AND NOT EXISTS (SELECT 1 FROM "group_swap_requests" WHERE "ticket_id" = NEW."id") THEN
    RAISE EXCEPTION 'group-swap ticket % has no request', NEW."id" USING ERRCODE = 'check_violation';
  END IF;
  RETURN NULL;
END $$;

CREATE CONSTRAINT TRIGGER "support_tickets_swap_request"
  AFTER INSERT ON "support_tickets"
  DEFERRABLE INITIALLY DEFERRED
  FOR EACH ROW EXECUTE FUNCTION "ftms_check_swap_ticket"();

-- ── Row Level Security (Supabase Data API gets nothing; see Phase 1) ────────
ALTER TABLE "support_tickets" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "ticket_messages" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "ticket_status_changes" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "ticket_attachments" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "group_swap_requests" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "group_swap_decisions" ENABLE ROW LEVEL SECURITY;

DO $$
DECLARE
  api_role TEXT;
BEGIN
  FOREACH api_role IN ARRAY ARRAY['anon', 'authenticated'] LOOP
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = api_role) THEN
      EXECUTE format('REVOKE ALL ON ALL TABLES IN SCHEMA public FROM %I', api_role);
      EXECUTE format('REVOKE ALL ON ALL SEQUENCES IN SCHEMA public FROM %I', api_role);
    END IF;
  END LOOP;
END $$;
